def add(a, b):
    return a + b

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def mean(xs):
    return sum(xs) / len(xs) if xs else 0.0

if __name__ == '__main__':
    print('add(2,3) =', add(2, 3))
    print('fib(10) =', fib(10))
    print('mean([1,2,3,4]) =', mean([1, 2, 3, 4]))

